using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using WoWProbe;
class QuickRandomTests
{
    static int passed,failed;
    static void Check(bool condition){if(!condition)throw new Exception("Unexpected result");}
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex);}}
    static QuickRoutePlan Plan()
    {
        var r=new RouteDocument{RouteId="random-test",Name="Original",RouteType="farm",Loop=true,MapId=42,MapMode=2,Zone="TEST"};
        foreach(var a in new[]{new[]{.5,.5},new[]{.52,.5},new[]{.52,.52},new[]{.5,.5}})r.Points.Add(new Waypoint{X=a[0],Y=a[1],Tolerance=.001});
        var p=new QuickRoutePlan{Route=r,RandomRoutes=true,TimedBreaks=true,SkillRows=new[]{"23","","32","",""},Calibration=new NavigationCalibration{MapId=42,MapMode=2,Zone="TEST",AxisScale=1.5,Confirmed=true,TurnRadiansPerSecond=5.85}};
        p.Vendor=new QuickVendorSettings{Enabled=true,RouteComplete=true,X=.55,Y=.5,Points=new List<Waypoint>{new Waypoint{X=.5,Y=.5,Tolerance=.0004},new Waypoint{X=.55,Y=.5,Tolerance=.0004}}};p.Repair=p.Vendor.Clone();return p;
    }
    static FarmObservation Observation(){return new FarmObservation{Fresh=true,KnownCore=true,Health=100,MapId=42,MapMode=2,Zone="TEST",X=.5,Y=.5,Facing=0,ChatOpenKnown=true,CastingKnown=true,TargetExists=true,TargetIdentityKnown=true,TargetToken=1,TargetName="Monster",TargetNameHash=1,NameHashKnown=true,AttackabilityKnown=true,TargetCanAttack=true,TargetDeadKnown=true,TargetReaction=4,RangeKnown=true,TargetInRange=true,CastEventsKnown=true};}
    static void Files(Action<string> body){string path=Path.Combine(Path.GetTempPath(),"quick-random-"+Guid.NewGuid()+".json");try{body(path);}finally{if(File.Exists(path))File.Delete(path);}}
    static int Main()
    {
        Test("five rows select nonempty entries and reject invalid configuration",()=>{var r=new QuickSkillRows(new[]{"23","","32"," ",null});for(int i=0;i<100;i++)Check(r.Choose()==0||r.Selected==2);bool bad=false;try{new QuickSkillRows(new string[5]);}catch(FormatException){bad=true;}Check(bad);});
        Test("each fight holds its chosen skill sequence and reports its row",()=>{for(int n=0;n<20;n++){var o=Observation();var e=new QuickCombat(o,100,false,null,"9","9",80,0,false,new[]{"23","","32","",""});string row=null;var keys=new List<ushort>();for(int t=0;t<5000&&keys.Count<6;t+=100){o.Sequence++;var c=e.Step(o,t);if(c.Reason.Contains("随机技能行")){Check(c.Report&&row==null);row=c.Reason.EndsWith("=23")?"23":"32";}if(c.Action==QuickAction.Skill){keys.Add(c.Key);o.CastSuccess++;}}Check(row!=null&&keys.Count==6);for(int i=0;i<keys.Count;i++)Check(keys[i]==row[i%2]);}});
        Test("route families have exact counts, deterministic distinct paths, fixed corners and bounded deviations",()=>{var p=Plan();string before=p.Route.Fingerprint();foreach(int count in new[]{20,10,5}){var variants=QuickRouteVariants.For(p,p.Route,count);Check(variants.Count==count+1);var hashes=new HashSet<string>();for(int v=0;v<variants.Count;v++){var r=variants[v];Check(hashes.Add(r.Fingerprint()));Check(r.MapId==42&&r.Loop&&r.Points[0].X==r.Points.Last().X&&r.Points[0].Y==r.Points.Last().Y);foreach(var w in p.Route.Points)Check(r.Points.Any(a=>a.X==w.X&&a.Y==w.Y));foreach(var w in r.Points)Check(p.DistanceToRoute(w.X,w.Y)<=p.RouteVariation+1e-10);Check(r.Fingerprint()==QuickRouteVariants.For(p,p.Route,count)[v].Fingerprint());}}Check(p.Route.Fingerprint()==before);});
        Test("corpse variants retain recorded route identity and exact endpoints",()=>{var p=Plan();var r=QuickRouteVariants.Service(p,p.Vendor);r.RouteType="corpse_run";r.RouteId="recorded-ghost";foreach(var v in QuickRouteVariants.For(p,r,5))Check(v.RouteId=="recorded-ghost"&&!v.Loop&&v.Points[0].X==.5&&v.Points.Last().X==.55);});
        Test("patrol switches only after completion and advances revision each lap",()=>{var p=Plan();var o=Observation();o.TargetExists=false;var f=new QuickRouteFollower(p,o);f.TickNearbySearch(o,0,true);f.TickNearbySearch(o,3000,true);o.Sequence++;f.Step(o,3000);int previous=f.RouteRevision;for(int i=0;i<100;i++){var w=f.Plan.Route.Points[f.TargetIndex];o.X=w.X;o.Y=w.Y;o.Sequence++;var command=f.Step(o,3100+i*100);Check(command.Action!=QuickAction.Stop);Check(f.RouteRevision==previous+f.Laps);if(f.Laps>=4)break;}Check(f.Laps>=4);});
        Test("NPC outbound and return differ and checkpoints preserve both choices and next waypoint",()=>{var p=Plan();var o=new OperationObservation{Fresh=true,Farm=Observation()};var e=new QuickVendorEngine(p,o);Check(e.OutboundChoice!=e.ReturnChoice);Files(path=>{var cp=e.Checkpoint;Check(cp.ReturnVariant!=null);QuickVendorCheckpoint.Save(path,cp);var saved=QuickVendorCheckpoint.Load(path);var restored=new QuickVendorEngine(saved,o).Checkpoint;Check(restored.OutboundChoice==cp.OutboundChoice&&restored.ReturnChoice==cp.ReturnChoice&&restored.ReturnVariant.Fingerprint()==cp.ReturnVariant.Fingerprint()&&restored.Path.Fingerprint()==cp.Path.Fingerprint()&&restored.Next==cp.Next);});});
        Test("old NPC checkpoints do not rerandomize a pending path",()=>{var p=Plan();p.RandomRoutes=false;var o=new OperationObservation{Fresh=true,Farm=Observation()};var cp=new QuickVendorEngine(p,o).Checkpoint;cp.Plan.RandomRoutes=true;var restored=new QuickVendorEngine(cp,o).Checkpoint;Check(restored.ReturnVariant==null&&restored.Outbound.Fingerprint()==cp.Outbound.Fingerprint());});
        Test("new settings survive save clone and import without sharing arrays",()=>{Files(path=>{var p=Plan();QuickRoutePlan.Save(path,p);var q=QuickRoutePlan.Load(path);Check(q.RandomRoutes&&q.TimedBreaks&&q.SkillRows[2]=="32");q.SkillRows[0]="8";Check(p.SkillRows[0]=="23");});});
        Test("one hundred unique extra times stay within two hours and repeated cycles change duration",()=>{var s=new QuickBreakSchedule();Check(s.ExtraPool.Length==100&&s.ExtraPool.Distinct().Count()==100&&s.ExtraPool.All(n=>n>=1&&n<=7200));for(int i=0;i<200;i++){int old=s.ExtraSeconds;s.ConfirmOnline(i);Check(s.ExtraSeconds!=old&&s.OnlineLimit>7200000&&s.OnlineLimit<=14400000);}});
        Test("cumulative active time includes all workflow phases but excludes explicit pause",()=>{var s=new QuickBreakSchedule();s.Activate(100);s.Tick(60100);s.Pause(120100);s.Activate(999999);s.Tick(1000099);Check(s.OnlineMilliseconds==120100);s.Tick(10);Check(s.OnlineMilliseconds==120100);});
        Test("deadline defers for combat death and casts then records actual menu confirmation",()=>{var s=new QuickBreakSchedule();s.Activate(0);s.Tick(s.OnlineLimit);Check(s.Due&&!s.RequestLogout(true,false,false)&&!s.RequestLogout(false,true,false)&&!s.RequestLogout(false,false,true));Check(s.RequestLogout(false,false,false)&&s.OfflineUntil==0);s.ConfirmOffline(1000);Check(new[]{13,15,18}.Contains(s.OfflineMinutes)&&s.OfflineUntil==1000+s.OfflineMinutes*60000L);long elapsed=s.OnlineMilliseconds;s.Tick(99999999);Check(s.OnlineMilliseconds==elapsed);});
        Test("offline deadline and chosen duration survive restart",()=>Files(path=>{var s=new QuickBreakSchedule();s.OnlineMilliseconds=s.OnlineLimit;s.RequestLogout(false,false,false);s.ConfirmOffline(1000);s.Save(path,true);var q=QuickBreakSchedule.Load(path);Check(q.Phase=="Offline"&&q.OfflineUntil==s.OfflineUntil&&q.ExtraSeconds==s.ExtraSeconds&&q.OnlineMilliseconds==s.OnlineMilliseconds);}));
        Test("menu labels require exact unambiguous matches and independent screen context",()=>{var enter=new QuickScreenText{Text="进 入 魔 兽 世 界"};Check(QuickMenuText.Find(new[]{enter},true)==enter&&!QuickMenuText.HasContext(new[]{enter},true));Check(QuickMenuText.Find(new[]{enter,enter},true)==null);Check(QuickMenuText.Find(new[]{new QuickScreenText{Text="请点击进入游戏"}},true)==null);Check(QuickMenuText.HasContext(new[]{new QuickScreenText{Text="删除角色"}},true));Check(QuickMenuText.Find(new[]{new QuickScreenText{Text="返回角色选择"}},false)!=null);Check(!QuickMenuText.HasContext(new[]{new QuickScreenText{Text="登录"}},true));});
        Console.WriteLine("Random runtime tests: "+passed+" passed, "+failed+" failed. No game input.");return failed==0?0:1;
    }
}
